def _merge_kv(self, ds):
    if ds is None:
        return ""
    elif isinstance(ds, string_types):
        return ds
    elif isinstance(ds, dict):
        buf = ""
        for (k, v) in ds.items():
            if k.startswith('_'):
                continue
            buf = buf + "%s=%s " % (k, v)
        buf = buf.strip()
        return buf
